DO $$ BEGIN CREATE TYPE "PurchaseType" AS ENUM ('PR','PO','RECEIPT','INVOICE'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE "MaterialMoveType" AS ENUM ('REQUEST','RETURN'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS "PurchaseDoc" ("id" TEXT PRIMARY KEY,"type" "PurchaseType" NOT NULL,"number" TEXT NOT NULL UNIQUE,"projectId" TEXT NOT NULL,"vendorId" TEXT,"docDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"status" "DocStatus" NOT NULL DEFAULT 'DRAFT',"sourceId" TEXT,"notes" TEXT,"accurateRef" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PurchaseDoc_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "PurchaseDoc_vendorId_fkey" FOREIGN KEY ("vendorId") REFERENCES "Vendor"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS "PurchaseLine" ("id" TEXT PRIMARY KEY,"purchaseDocId" TEXT NOT NULL,"rabItemId" TEXT,"itemId" TEXT NOT NULL,"description" TEXT NOT NULL,"qty" DECIMAL(18,4) NOT NULL,"unit" TEXT,"unitPrice" DECIMAL(18,2) NOT NULL DEFAULT 0,CONSTRAINT "PurchaseLine_purchaseDocId_fkey" FOREIGN KEY ("purchaseDocId") REFERENCES "PurchaseDoc"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "PurchaseLine_rabItemId_fkey" FOREIGN KEY ("rabItemId") REFERENCES "RabItem"("id") ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT "PurchaseLine_itemId_fkey" FOREIGN KEY ("itemId") REFERENCES "Item"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS "MaterialMove" ("id" TEXT PRIMARY KEY,"type" "MaterialMoveType" NOT NULL,"number" TEXT NOT NULL UNIQUE,"projectId" TEXT NOT NULL,"moveDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"warehouseName" TEXT,"notes" TEXT,"status" "DocStatus" NOT NULL DEFAULT 'DRAFT',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "MaterialMove_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS "MaterialMoveLine" ("id" TEXT PRIMARY KEY,"materialMoveId" TEXT NOT NULL,"rabItemId" TEXT,"itemId" TEXT NOT NULL,"qty" DECIMAL(18,4) NOT NULL,"unit" TEXT,CONSTRAINT "MaterialMoveLine_materialMoveId_fkey" FOREIGN KEY ("materialMoveId") REFERENCES "MaterialMove"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "MaterialMoveLine_rabItemId_fkey" FOREIGN KEY ("rabItemId") REFERENCES "RabItem"("id") ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT "MaterialMoveLine_itemId_fkey" FOREIGN KEY ("itemId") REFERENCES "Item"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
